tuningTable.comment:
Each row maps a dataset onto an ID for which the dataset contains data;
     each dataset gets one such row.
     Used in dataset record queries.

tuningTable.sql:

DO $$
DECLARE
  skiplist RECORD;
BEGIN
  FOR skiplist
      IN (SELECT taxon_id, max(parent_id) as parent_id, max(tree_level)
          FROM DistinctTaxonLink&1
          WHERE display_reason in ('none', 'has data')
          GROUP by taxon_id
          ORDER by max(tree_level) desc
         )
  LOOP
    UPDATE DistinctTaxonLink&1
    SET parent_id
        = (SELECT max(parent_id)
           FROM DistinctTaxonLink&1
           WHERE taxon_id = skiplist.taxon_id)
    WHERE parent_id = skiplist.taxon_id;
  END LOOP;
  commit;
END;
$$ LANGUAGE PLPGSQL;

tuningTable.comment:
Each row maps a dataset onto an ID for which the dataset contains data;
     each dataset gets one such row.
     Used in dataset record queries.

tuningTable.sql:

DO $$
DECLARE
  -- Declare a record variable to hold each nodeset record
  nodeset RECORD;
  rows INTEGER := 0;
  start_time timestamptz;
  end_time timestamptz;
BEGIN
  -- Loop through each dataset/experiment and compute & insert results into the temp table
  -- Excluding quantitative_massSpec_diffresult otherwise we will get duplicates
  FOR nodeset IN SELECT node_set_id, node_type FROM study.nodeset where node_type != 'quantitative_massSpec_diffresult' LOOP
    start_time := clock_timestamp();
      INSERT INTO profile_nafeatureexp_summary
      SELECT sl.node_set_id, result.na_feature_id, nodeset.node_type,
        string_agg(coalesce(round(result.value::numeric, 2)::varchar, 'NA'), chr(9) order by pan.node_order_num) as profile_as_string_value,
        string_agg(coalesce(round(result.standard_error::numeric, 2)::varchar, 'NA'), chr(9) order by pan.node_order_num) as profile_as_string_stderr,
        string_agg(coalesce(round(result.percentile_channel1::numeric, 2)::varchar, 'NA'), chr(9) order by pan.node_order_num) as profile_as_string_percentile1,
        string_agg(coalesce(round(result.percentile_channel2::numeric, 2)::varchar, 'NA'), chr(9) order by pan.node_order_num) as profile_as_string_percentile2
      FROM study.ProtocolAppNode pan, NodeSetOutputNode sl, results.NaFeatureExpression result
      WHERE result.protocol_app_node_id = sl.protocol_app_node_id
        AND result.protocol_app_node_id = pan.protocol_app_node_id
        AND sl.node_set_id = nodeset.node_set_id
      GROUP BY sl.node_set_id, result.na_feature_id, nodeset.node_type
    ;
    end_time := clock_timestamp();
    rows := rows +1;
    -- raise notice '% inserted nodeset % in % ms', rows, nodeset.node_set_id, EXTRACT(EPOCH FROM (end_time - start_time)) * 1000;
  END LOOP;
END $$;


create table profile_p&1 (
 like profile
)  PARTITION BY LIST (org_abbrev)


        DO $$
        DECLARE
          orgrecord RECORD;
          partition_name TEXT;
        BEGIN
          FOR orgrecord IN SELECT org_abbrev, sanitized_org_abbrev from webready.OrganismAbbreviation_p LOOP
            partition_name := lower('profile_p&1_' || orgrecord.sanitized_org_abbrev);
            EXECUTE format('CREATE TABLE %I PARTITION OF Profile_p&1 FOR VALUES IN (%L)', partition_name, orgrecord.org_abbrev);

            INSERT INTO Profile_p&1
            Select *
	    FROM profile p
	    WHERE org_abbrev = orgrecord.org_abbrev;
          END LOOP;
        END $$;

do $$ declare orgrecord RECORD; partition_name TEXT; begin FOR orgrecord IN SELECT org_abbrev, sanitized_org_abbrev from webready.OrganismAbbreviation_p LOOP
partition_name := lower('&prefixallgeneproducts_p&1_' || orgrecord.sanitized_org_abbrev); EXECUTE format('CREATE TABLE %I PARTITION OF &prefixAllGeneProducts_p&1 FOR VALUES IN (%L)', partition_name, orgrecord.org_abbrev);
insert into &prefixAllGeneProducts_p&1 select ta.gene_source_id AS source_id, tp.product, ta.project_id, CASE tp.is_preferred WHEN 1 THEN 'No' WHEN 0 THEN 'Yes' END as is_alternate, string_agg(ta.source_id, ', ' order by ta.source_id) as transcript_ids, string_agg(tp.publication, ', ' order by ta.source_id) as reference, e.name as evidence_code, tp.with_from as evidence_code_parameter, COALESCE(tp.assigned_by, o.genome_source) as assigned_by, 'apidb.TranscriptProduct' as source, orgrecord.org_abbrev from webready.TranscriptAttributes_p ta INNER JOIN apidb.TranscriptProduct tp ON ta.na_feature_id = tp.na_feature_id INNER JOIN apidb.Organism o ON o.abbrev = ta.org_abbrev LEFT JOIN all_gene_product_evids e ON tp.evidence_code = e.go_evidence_code_id where ta.org_abbrev = orgrecord.org_abbrev group by ta.gene_source_id, ta.project_id, tp.product, tp.is_preferred, e.name, tp.with_from, tp.assigned_by, o.genome_source;
insert into &prefixAllGeneProducts_p&1 select ga.source_id as source_id, gfp.product, ga.project_id, CASE gfp.is_preferred WHEN 1 THEN 'No' WHEN 0 THEN 'Yes' END as is_alternate, null as transcript_ids, gfp.publication as reference, e.name as evidence_code, gfp.with_from as evidence_code_parameter, COALESCE(gfp.assigned_by, o.genome_source) as assigned_by, 'apidb.GeneFeatureProduct' as source, orgrecord.org_abbrev from apidb.GeneFeatureProduct gfp INNER JOIN webready.GeneAttributes_p ga ON ga.na_feature_id = gfp.na_feature_id INNER JOIN apidb.Organism o ON o.abbrev = ga.org_abbrev LEFT JOIN all_gene_product_evids e ON gfp.evidence_code = e.go_evidence_code_id WHERE ga.org_abbrev = orgrecord.org_abbrev;
insert into &prefixAllGeneProducts_p&1 select ga.source_id as source_id, gf.product, ga.project_id, null as is_alternate, null as transcript_ids, null as reference, null as evidence_code, null as evidence_code_parameter, o.genome_source as assigned_by, 'dots.GeneFeature' as source, orgrecord.org_abbrev from dots.GeneFeature gf, webready.GeneAttributes_p ga, webready.GeneProduct_p gp, apidb.Organism o where ga.na_feature_id = gf.na_feature_id and o.abbrev = orgrecord.org_abbrev and gf.product is not null and TRIM(gf.product) != '' and gf.product !~* '(hypothetical[_ ]protein|unspecified product|unnamed protein product|conserved hypothetical protein|predicted protein|protein of unknown function|uncharacterized protein|conserved protein,\s*unknown function|---na---|contig)' and NOT (gf.product ~* '^has domain\(s\) with predicted' AND (gf.product LIKE '%,%' OR gf.product ~* ' and ')) and NOT (gf.product NOT LIKE '% %' AND gf.product LIKE 'XM%') and gf.product !~ '^CAD\d+(\.\d+)?$' and gf.product !~* 'conserved\s+\w+\s+protein,?\s*unknown\s+function' and gf.product !~* 'uncharacterized\s+loc\d+' and gf.product NOT LIKE 'CSON%' and gf.product NOT LIKE 'hypothetical protein BGH%' and gf.product NOT LIKE 'DEHA2A%' and NOT (gf.product NOT LIKE '% %' AND (gf.product ~ '^[A-Z]{2,4}\d{4,}$' OR gf.product ~ '^[A-Z]{3,5}_\d+$' OR gf.product ~ '^LOC\d+$' OR gf.product ~ '^[A-Z]+\d+\.[0-9]+$')) and gf.product NOT LIKE 'Similar to [%' and gf.product NOT LIKE '%UniProtKB%' and LOWER(TRIM(gf.product)) NOT IN ('protein', 'gene product', 'gene', 'orf') and ga.source_id = gp.source_id and gp.org_abbrev = orgrecord.org_abbrev and ga.org_abbrev = orgrecord.org_abbrev and gp.source_rule >= 11; -- no product from curated sources (tiers 1-5, rules 1-10)
insert into &prefixAllGeneProducts_p&1 select ta.gene_source_id AS source_id, t.product, ta.project_id, null as is_alternate, string_agg(ta.source_id, ', ' order by ta.source_id) as transcript_ids, null as reference, null as evidence_code, null as evidence_code_parameter, o.genome_source as assigned_by, 'dots.Transcript' as source, orgrecord.org_abbrev from webready.TranscriptAttributes_p ta, dots.Transcript t, apidb.Organism o where ta.na_feature_id = t.na_feature_id and o.abbrev = ta.org_abbrev and t.product is not null and TRIM(t.product) != '' and t.product !~* '(hypothetical[_ ]protein|unspecified product|unnamed protein product|conserved hypothetical protein|predicted protein|protein of unknown function|uncharacterized protein|conserved protein,\s*unknown function|---na---|contig)' and NOT (t.product ~* '^has domain\(s\) with predicted' AND (t.product LIKE '%,%' OR t.product ~* ' and ')) and NOT (t.product NOT LIKE '% %' AND t.product LIKE 'XM%') and t.product !~ '^CAD\d+(\.\d+)?$' and t.product !~* 'conserved\s+\w+\s+protein,?\s*unknown\s+function' and t.product !~* 'uncharacterized\s+loc\d+' and t.product NOT LIKE 'CSON%' and t.product NOT LIKE 'hypothetical protein BGH%' and t.product NOT LIKE 'DEHA2A%' and NOT (t.product NOT LIKE '% %' AND (t.product ~ '^[A-Z]{2,4}\d{4,}$' OR t.product ~ '^[A-Z]{3,5}_\d+$' OR t.product ~ '^LOC\d+$' OR t.product ~ '^[A-Z]+\d+\.[0-9]+$')) and t.product NOT LIKE 'Similar to [%' and t.product NOT LIKE '%UniProtKB%' and LOWER(TRIM(t.product)) NOT IN ('protein', 'gene product', 'gene', 'orf') and ta.org_abbrev = orgrecord.org_abbrev and ta.gene_source_id not in (select source_id from webready.GeneProduct_p where source_rule < 23 and org_abbrev = orgrecord.org_abbrev) -- product only in dots.Transcript group by ta.gene_source_id, ta.project_id, t.product, o.genome_source;
insert into &prefixAllGeneProducts_p&1 select gp.source_id, gp.product, ga.project_id, null as is_alternate, null as transcript_ids, null as reference, null as evidence_code, null as evidence_code_parameter, o.genome_source as assigned_by, gp.source_rule_description as source, orgrecord.org_abbrev from webready.GeneProduct_p gp inner join webready.GeneAttributes_p ga on ga.source_id = gp.source_id and ga.org_abbrev = orgrecord.org_abbrev inner join apidb.Organism o on o.abbrev = orgrecord.org_abbrev where gp.source_rule < 94 and gp.org_abbrev = orgrecord.org_abbrev and not exists ( select 1 from &prefixAllGeneProducts_p&1 agp where agp.source_id = gp.source_id and agp.product = gp.product and agp.org_abbrev = orgrecord.org_abbrev );
end loop; end $$;

DO $$ DECLARE rec RECORD; av_table TEXT; ag_table TEXT; entity_col TEXT; has_gene_id INTEGER; BEGIN FOR rec IN SELECT DISTINCT dds.dataset_presenter_id AS dataset_id, s.internal_abbrev AS study_abbrev, e.internal_abbrev AS entity_abbrev FROM eda.study s JOIN eda.entitytypegraph e ON s.study_id = e.study_id JOIN eda.studyexternaldatabaserelease sedr ON s.study_id = sedr.study_id JOIN sres.externaldatabaserelease edr ON sedr.external_database_release_id = edr.external_database_release_id JOIN sres.externaldatabase ed ON edr.external_database_id = ed.external_database_id JOIN apidbtuning.datasetdatasource dds ON ed.name = dds.name WHERE dds.category = 'Phenotype' AND s.internal_abbrev IS NOT NULL LOOP av_table := 'eda.attributevalue_' || rec.study_abbrev || '_' || lower(rec.entity_abbrev); ag_table := 'eda.attributegraph_' || rec.study_abbrev || '_' || lower(rec.entity_abbrev); entity_col := lower(rec.entity_abbrev) || '_stable_id';
-- Skip if either dynamic table does not exist IF to_regclass(av_table) IS NULL OR to_regclass(ag_table) IS NULL THEN CONTINUE; END IF;
-- Skip entity types that have no VEUPATHDB_GENE_ID attribute EXECUTE format( 'SELECT count(*) FROM %s WHERE stable_id = %L', ag_table, 'VEUPATHDB_GENE_ID' ) INTO has_gene_id;
IF has_gene_id = 0 THEN CONTINUE; END IF;
-- Insert one row per (gene, categorical variable, value) combination EXECUTE format( 'INSERT INTO GenePhenotypeCategoricalValue&1 (gene_source_id, dataset_id, variable_source_id, variable_display_name, value) WITH gene_ids AS ( SELECT %I AS entity_id, string_value AS gene_source_id FROM %s WHERE attribute_stable_id = %L ), cat_vars AS ( SELECT stable_id, display_name FROM %s WHERE data_shape = %L AND stable_id != %L ) SELECT g.gene_source_id, %L, av.attribute_stable_id, cv.display_name, av.string_value FROM %s av JOIN gene_ids g ON av.%I = g.entity_id JOIN cat_vars cv ON av.attribute_stable_id = cv.stable_id WHERE av.string_value IS NOT NULL', entity_col, -- %I: entity row id column in gene_ids CTE av_table, -- %s: attributevalue table in gene_ids CTE 'VEUPATHDB_GENE_ID', -- %L: gene id attribute filter ag_table, -- %s: attributegraph table in cat_vars CTE 'categorical', -- %L: data_shape filter 'VEUPATHDB_GENE_ID', -- %L: exclude gene id variable itself rec.dataset_id, -- %L: literal dataset_presenter_id value av_table, -- %s: attributevalue table in main query entity_col -- %I: join column for entity row id ); END LOOP; END $$;

DO $$ DECLARE rec RECORD; ag_table TEXT; BEGIN FOR rec IN SELECT DISTINCT COALESCE(dds.dataset_presenter_id, s.stable_id) AS dataset_id, s.internal_abbrev AS study_abbrev, e.internal_abbrev AS entity_abbrev, e.stable_id AS entity_stable_id, e.study_id AS study_id FROM eda.study s JOIN eda.entitytypegraph e ON s.study_id = e.study_id LEFT JOIN eda.studyexternaldatabaserelease sedr ON s.study_id = sedr.study_id LEFT JOIN sres.externaldatabaserelease edr ON sedr.external_database_release_id = edr.external_database_release_id LEFT JOIN sres.externaldatabase ed ON edr.external_database_id = ed.external_database_id LEFT JOIN datasetdatasource dds ON ed.name = dds.name WHERE s.internal_abbrev IS NOT NULL LOOP ag_table := 'eda.attributegraph_' || rec.study_abbrev || '_' || lower(rec.entity_abbrev);
IF to_regclass(ag_table) IS NULL THEN CONTINUE; END IF;
EXECUTE format( 'INSERT INTO DatasetCategoricalValue&1 (dataset_id, study_id, variable_source_id, stable_id, entity_stable_id, value) SELECT %L, etg.study_id, ag.stable_id, ag.stable_id, etg.stable_id as entity_stable_id, v.value FROM %s ag, eda.entitytypegraph etg CROSS JOIN LATERAL jsonb_array_elements_text(ag.vocabulary::jsonb) AS v(value) WHERE ag.data_shape = %L AND etg.stable_id = %L AND etg.study_id = %L AND ag.vocabulary IS NOT NULL AND ag.stable_id != %L', rec.dataset_id, -- %L: literal dataset_id value ag_table, -- %s: attributegraph table 'categorical', -- %L rec.entity_stable_id, -- %L: literal entity_stable_id value rec.study_id, -- %L: literal study_id value 'VEUPATHDB_GENE_ID' -- %L: exclude gene id variable ); END LOOP; END $$;

DO $$ DECLARE rec RECORD; ag_table TEXT; BEGIN FOR rec IN SELECT DISTINCT COALESCE(dds.dataset_presenter_id, s.stable_id) AS dataset_id, s.internal_abbrev AS study_abbrev, s.study_id AS study_id, e.internal_abbrev AS entity_abbrev, e.stable_id AS entity_stable_id FROM eda.study s JOIN eda.entitytypegraph e ON s.study_id = e.study_id LEFT JOIN eda.studyexternaldatabaserelease sedr ON s.study_id = sedr.study_id LEFT JOIN sres.externaldatabaserelease edr ON sedr.external_database_release_id = edr.external_database_release_id LEFT JOIN sres.externaldatabase ed ON edr.external_database_id = ed.external_database_id LEFT JOIN datasetdatasource dds ON ed.name = dds.name WHERE s.internal_abbrev IS NOT NULL LOOP ag_table := 'eda.attributegraph_' || rec.study_abbrev || '_' || lower(rec.entity_abbrev);
IF to_regclass(ag_table) IS NULL THEN CONTINUE; END IF;
EXECUTE format( 'INSERT INTO DatasetVariable&1 (dataset_id, study_id, entity_stable_id, variable_source_id, variable_display_name, variable_definition, stable_id, display_name, definition, data_shape, data_type, display_range_max, display_range_min, display_type, provider_label, hidden) SELECT %L, etg.study_id, etg.stable_id as entity_stable_id, ag.stable_id, ag.display_name, ag.definition, ag.stable_id, ag.display_name, ag.definition, data_shape, data_type, display_range_max, display_range_min, display_type, ag.provider_label, ag.hidden FROM %s ag, eda.entitytypegraph etg WHERE ag.stable_id != %L AND etg.stable_id = %L AND etg.study_id = %L', rec.dataset_id, -- %L: literal dataset_id value ag_table, -- %s: attributegraph table 'VEUPATHDB_GENE_ID', -- %L: exclude gene id variable rec.entity_stable_id, -- %L: literal entity_stable_id value rec.study_id -- %L: literal study_id ); END LOOP; END $$;
